mkuse!{use std :: num :: NonZero ;}
mkuse!{use rustc_abi :: { FieldIdx , FieldsShape , VariantIdx , Variants } ;}
mkuse!{use rustc_index :: IndexVec ;}
mkuse!{use rustc_middle :: mir :: interpret :: InterpResult ;}
mkuse!{use rustc_middle :: ty :: { self , Ty } ;}
mkuse!{use tracing :: trace ;}
mkuse!{use super :: { InterpCx , MPlaceTy , Machine , Projectable , interp_ok , throw_inval } ;}
mkitem!{mktrait!{# [doc = " How to traverse a value and what to do when we are at the leaves."] pub trait ValueVisitor < 'tcx , M : Machine < 'tcx > > : Sized { type V : Projectable < 'tcx , M :: Provenance > + From < MPlaceTy < 'tcx , M :: Provenance > > ; # [doc = " The visitor must have an `InterpCx` in it."] fn ecx (& self) -> & InterpCx < 'tcx , M > ; # [doc = " `read_discriminant` can be hooked for better error messages."] # [inline (always)] fn read_discriminant (& mut self , v : & Self :: V) -> InterpResult < 'tcx , VariantIdx > { self . ecx () . read_discriminant (& v . to_op (self . ecx ()) ?) } # [doc = " This function provides the chance to reorder the order in which fields are visited for"] # [doc = " `FieldsShape::Aggregate`."] # [doc = ""] # [doc = " The default means we iterate in source declaration order; alternatively this can do some"] # [doc = " work with `memory_index` to iterate in memory order."] # [inline (always)] fn aggregate_field_iter (memory_index : & IndexVec < FieldIdx , u32 > ,) -> impl Iterator < Item = FieldIdx > + 'static { memory_index . indices () } # [doc = " Visits the given value, dispatching as appropriate to more specialized visitors."] # [inline (always)] fn visit_value (& mut self , v : & Self :: V) -> InterpResult < 'tcx > { self . walk_value (v) } # [doc = " Visits the given value as a union. No automatic recursion can happen here."] # [inline (always)] fn visit_union (& mut self , _v : & Self :: V , _fields : NonZero < usize >) -> InterpResult < 'tcx > { interp_ok (()) } # [doc = " Visits the given value as the pointer of a `Box`. There is nothing to recurse into."] # [doc = " The type of `v` will be a raw pointer to `T`, but this is a field of `Box<T>` and the"] # [doc = " pointee type is the actual `T`. `box_ty` provides the full type of the `Box` itself."] # [inline (always)] fn visit_box (& mut self , _box_ty : Ty < 'tcx > , _v : & Self :: V) -> InterpResult < 'tcx > { interp_ok (()) } # [doc = " Called each time we recurse down to a field of a \"product-like\" aggregate"] # [doc = " (structs, tuples, arrays and the like, but not enums), passing in old (outer)"] # [doc = " and new (inner) value."] # [doc = " This gives the visitor the chance to track the stack of nested fields that"] # [doc = " we are descending through."] # [inline (always)] fn visit_field (& mut self , _old_val : & Self :: V , _field : usize , new_val : & Self :: V ,) -> InterpResult < 'tcx > { self . visit_value (new_val) } # [doc = " Called when recursing into an enum variant."] # [doc = " This gives the visitor the chance to track the stack of nested fields that"] # [doc = " we are descending through."] # [inline (always)] fn visit_variant (& mut self , _old_val : & Self :: V , _variant : VariantIdx , new_val : & Self :: V ,) -> InterpResult < 'tcx > { self . visit_value (new_val) } # [doc = " Traversal logic; should not be overloaded."] fn walk_value (& mut self , v : & Self :: V) -> InterpResult < 'tcx > { let ty = v . layout () . ty ; trace ! ("walk_value: type: {ty}") ; match * ty . kind () { ty :: Dynamic (data , _ , ty :: Dyn) => { let op = v . to_op (self . ecx ()) ? ; let dest = op . assert_mem_place () ; let inner_mplace = self . ecx () . unpack_dyn_trait (& dest , data) ? ; trace ! ("walk_value: dyn object layout: {:#?}" , inner_mplace . layout) ; return self . visit_field (v , 0 , & inner_mplace . into ()) ; } ty :: Adt (def , ..) if def . is_box () => { assert_eq ! (v . layout () . fields . count () , 2 , "`Box` must have exactly 2 fields") ; let [unique_ptr , alloc] = self . ecx () . project_fields (v , [FieldIdx :: ZERO , FieldIdx :: ONE]) ? ; assert_eq ! (unique_ptr . layout () . fields . count () , 2) ; let [nonnull_ptr , phantom] = self . ecx () . project_fields (& unique_ptr , [FieldIdx :: ZERO , FieldIdx :: ONE]) ? ; assert ! (phantom . layout () . ty . ty_adt_def () . is_some_and (| adt | adt . is_phantom_data ()) , "2nd field of `Unique` should be PhantomData but is {:?}" , phantom . layout () . ty ,) ; assert_eq ! (nonnull_ptr . layout () . fields . count () , 1) ; let raw_ptr = self . ecx () . project_field (& nonnull_ptr , FieldIdx :: ZERO) ? ; self . visit_box (ty , & raw_ptr) ? ; self . visit_field (v , 1 , & alloc) ? ; return interp_ok (()) ; } ty :: Param (..) | ty :: Alias (..) | ty :: Bound (..) | ty :: Placeholder (..) | ty :: Infer (..) | ty :: Error (..) => throw_inval ! (TooGeneric) , _ => { } } ; match & v . layout () . fields { FieldsShape :: Primitive => { } & FieldsShape :: Union (fields) => { self . visit_union (v , fields) ? ; } FieldsShape :: Arbitrary { memory_index , .. } => { for idx in Self :: aggregate_field_iter (memory_index) { let field = self . ecx () . project_field (v , idx) ? ; self . visit_field (v , idx . as_usize () , & field) ? ; } } FieldsShape :: Array { .. } => { let mut iter = self . ecx () . project_array_fields (v) ? ; while let Some ((idx , field)) = iter . next (self . ecx ()) ? { self . visit_field (v , idx . try_into () . unwrap () , & field) ? ; } } } match v . layout () . variants { Variants :: Multiple { .. } => { let idx = self . read_discriminant (v) ? ; let inner = self . ecx () . project_downcast (v , idx) ? ; trace ! ("walk_value: variant layout: {:#?}" , inner . layout ()) ; self . visit_variant (v , idx , & inner) ? ; } Variants :: Single { .. } | Variants :: Empty => { } } interp_ok (()) } }}}